input.command:
$plan = Get-Content -Raw -LiteralPath '.recursive/run/115-effect-foldkit-runtime-migration/02-to-be-plan.md'
$req = Get-Content -Raw -LiteralPath '.recursive/run/115-effect-foldkit-runtime-migration/00-requirements.md'
$norm = { param($s) ($s -replace '\s+',' ').Trim() }
$reqN = & $norm $req
$rx = [regex]'(?m)^- ((?:SRC-\d{3})|R\d+) \| Source Quote: (.*?) \| Coverage:'
$ms = $rx.Matches($plan)
$ids = @{}; $bad = @()
foreach($m in $ms){ $id=$m.Groups[1].Value; $q=& $norm $m.Groups[2].Value; $ids[$id]=$true; if(-not $reqN.Contains($q)){ $bad += $id } }
"IDs=$(($ids.Keys|Measure-Object).Count) Matches=$($ms.Count) MissingQuote=$($bad.Count)"
if($bad.Count){ "Mismatch: $($bad -join ', ')" }
$missing = @('R1') | Out-Null
$rq = [regex]::Matches($req,'(?m)^### `(R\d+|SRC-\d{3})`') | ForEach-Object { $_.Groups[1].Value }
"ReqIDs=$($rq.Count) PlanNotInReq=$(($ids.Keys | Where-Object { $rq -notcontains $_ }).Count) ReqNotInPlan=$(($rq | Where-Object { -not $ids.ContainsKey($_) }).Count)"
